growth_attach_radius_ok :: proc(t: ^Topology, anchor_slot: u32, pos: [2]i32, radius: i32) -> bool {
	if radius < 1 {
		return false // degenerate guard — never a silent zero-radius accept
	}
	d := t.node_pos[anchor_slot] - pos
	r2 := i64(radius) * i64(radius)
	return i64(d[0])*i64(d[0]) + i64(d[1])*i64(d[1]) <= r2
}
